import React, { useState, useEffect } from "react";
import { Plus } from "lucide-react";
import axios from "axios";

import JobStats from "../components/JobStats";
import JobTable from "../components/JobTable";
import JobForm from "../components/JobForm";
import ApplicationsTable from "../components/ApplicationsTable";

function JobAdminPage() {
  const [jobs, setJobs] = useState([]);
  const [applications, setApplications] = useState([]);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingJob, setEditingJob] = useState(null);
  const [activeTab, setActiveTab] = useState("jobs");

  // --- Fetch jobs ---
  const fetchJobs = async () => {
    try {
      const res = await axios.get("http://localhost:5000/api/jobs");
      console.log("✅ Fetched jobs from server:", res.data);
      setJobs(res.data);
    } catch (err) {
      console.error("Failed to fetch jobs:", err.response || err);
      alert("Failed to fetch jobs. Check console.");
    }
  };

  // --- Fetch applications ---
  const fetchApplications = async () => {
    try {
      const res = await axios.get("http://localhost:5000/api/applications");
      setApplications(res.data);
    } catch (err) {
      console.error("Failed to fetch applications:", err.response || err);
      alert("Failed to fetch applications. Check console.");
    }
  };

  useEffect(() => {
    fetchJobs();
    fetchApplications();
  }, []);

  // --- Add or Update Job ---
  const addOrUpdateJob = async (jobData) => {
    console.log("📥 JobAdminPage - Data received from JobForm:", jobData);

    // CRITICAL: Send the data exactly as received, don't modify jobType
    const payload = {
      title: jobData.title,
      role: jobData.role,
      skillset: jobData.skillset,
      ctc: jobData.ctc,
      location: jobData.location,
      experience: jobData.experience,
      jobType: jobData.jobType, // IMPORTANT: Don't add || "Full-time" here
      department: jobData.department,
      description: jobData.description,
      responsibilities: jobData.responsibilities,
      qualifications: jobData.qualifications,
      benefits: jobData.benefits,
      deadline: jobData.deadline
    };

    console.log("📤 JobAdminPage - Payload being sent to backend:", payload);
    console.log("🎯 JobType in payload:", payload.jobType);

    try {
      if (editingJob) {
        console.log("🔄 Updating job with ID:", editingJob._id);
        const res = await axios.put(
          `http://localhost:5000/api/jobs/${editingJob._id}`, 
          payload
        );
        console.log("✅ Backend response (UPDATE):", res.data);

        // Update the jobs list
        setJobs(jobs.map(j => j._id === editingJob._id ? res.data : j));
        setEditingJob(null);
        alert("Job updated successfully!");
      } else {
        console.log("➕ Creating new job");
        const res = await axios.post("http://localhost:5000/api/jobs", payload);
        console.log("✅ Backend response (CREATE):", res.data);

        // Add to jobs list
        setJobs([...jobs, res.data]);
        alert("Job added successfully!");
      }

      setIsFormOpen(false);

      // Refresh the jobs list to ensure we have the latest data
      setTimeout(() => fetchJobs(), 500);

    } catch (err) {
      console.error("❌ Error adding/updating job:", err);
      console.error("❌ Error response:", err.response?.data);
      alert(`Failed to add/update job. Error: ${err.response?.data?.error || err.message}`);
    }
  };

  // --- Edit Job ---
  const handleEdit = (job) => {
    console.log("📝 JobAdminPage - Editing job:", job);
    setEditingJob(job);
    setIsFormOpen(true);
  };

  // --- Delete Job ---
  const handleDelete = async (_id) => {
    if (!window.confirm("Are you sure you want to delete this job posting?")) return;

    try {
      console.log("🗑️ Deleting job with ID:", _id);
      await axios.delete(`http://localhost:5000/api/jobs/${_id}`);
      setJobs(jobs.filter(job => job._id !== _id));
      alert("Job deleted successfully!");
    } catch (err) {
      console.error("Error deleting job:", err.response || err);
      alert("Failed to delete job. Check console for details.");
    }
  };

  // --- Styles ---
  const styles = {
    page: { minHeight: "100vh", padding: "40px", backgroundColor: "#f5f7fb" },
    container: { maxWidth: "1200px", margin: "0 auto" },
    headerCard: {
      background: "#fff",
      borderRadius: "12px",
      padding: "25px 30px",
      display: "flex",
      alignItems: "center",
      justifyContent: "space-between",
      boxShadow: "0 2px 12px rgba(0,0,0,0.05)",
      marginBottom: "20px",
    },
    addButton: {
      display: "flex",
      alignItems: "center",
      gap: "8px",
      backgroundColor: "#2563eb",
      color: "#fff",
      border: "none",
      borderRadius: "8px",
      padding: "10px 18px",
      fontSize: "15px",
      cursor: "pointer",
    },
    tabs: { display: "flex", gap: "20px", marginBottom: "20px", cursor: "pointer" },
    tab: (active) => ({
      padding: "10px 20px",
      borderRadius: "8px",
      backgroundColor: active ? "#2563eb" : "#fff",
      color: active ? "#fff" : "#1e293b",
      fontWeight: active ? "600" : "500",
      boxShadow: active ? "0 2px 8px rgba(0,0,0,0.1)" : "none",
      cursor: "pointer",
    }),
  };

  return (
    <div style={styles.page}>
      <div style={styles.container}>
        {/* Header */}
        <div style={styles.headerCard}>
          <h1 style={{ fontSize: "28px", fontWeight: "700" }}>Job Administration</h1>
          {activeTab === "jobs" && (
            <button 
              style={styles.addButton} 
              onClick={() => {
                setEditingJob(null);
                setIsFormOpen(true);
              }}
            >
              <Plus size={20} /> Add New Job
            </button>
          )}
        </div>

        {/* Tabs */}
        <div style={styles.tabs}>
          <div style={styles.tab(activeTab === "jobs")} onClick={() => setActiveTab("jobs")}>
            Jobs ({jobs.length})
          </div>
          <div style={styles.tab(activeTab === "applications")} onClick={() => setActiveTab("applications")}>
            Received Applications ({applications.length})
          </div>
        </div>

        {/* Tab Content */}
        {activeTab === "jobs" ? (
          <>
            <JobStats jobs={jobs} />
            <JobTable jobs={jobs} onEdit={handleEdit} onDelete={handleDelete} />
          </>
        ) : (
          <ApplicationsTable applications={applications} onRefresh={fetchApplications} />
        )}

        {/* Job Form Modal */}
        {isFormOpen && (
          <JobForm
            job={editingJob}
            onClose={() => {
              setIsFormOpen(false);
              setEditingJob(null);
            }}
            onSubmit={addOrUpdateJob}
          />
        )}
      </div>
    </div>
  );
}

export default JobAdminPage;
